def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(x, default=(0, 0)):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return default

    def step_toward(a, b):
        ax, ay = pos(a)
        bx, by = pos(b)
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        ax, ay = pos(a)
        bx, by = pos(b)
        return abs(ax - bx) + abs(ay - by)

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))

    grid_w = observation.get("grid_width", 0) or 0
    grid_h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = [
            (0, 0),
            (0, grid_h - 1 if grid_h else 0),
            (grid_w - 1 if grid_w else 0, 0),
            (grid_w - 1 if grid_w else 0, grid_h - 1 if grid_h else 0),
        ]
        target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
        return step_toward((sx, sy), target)

    if env == "territory_control":
        candidates = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier")
            or observation.get("targets")
            or []
        )
        best = None
        best_score = None
        for item in candidates:
            p = pos(item, None)
            if p is None:
                continue
            d = manhattan((sx, sy), p)
            if best is None or d < best_score:
                best = p
                best_score = d
        if best is not None:
            return step_toward((sx, sy), best)
        return step_toward((sx, sy), (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for item in resources:
        p = pos(item, None)
        if p is None:
            continue
        d = manhattan((sx, sy), p)
        if best is None or d < best_score:
            best = p
            best_score = d
    if best is not None:
        return step_toward((sx, sy), best)

    if env == "resource_collection":
        return step_toward((sx, sy), (ox, oy))

    return [0, 0]

